namespace sv_de4e92b61854483da75d1cdae0b374ba.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_de4e92b61854483da75d1cdae0b374ba.Components.Pages.Settings

<nav class="settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_de4e92b61854483da75d1cdae0b374ba.Components.Pages.Settings
@using sv_de4e92b61854483da75d1cdae0b374ba.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (_showSuccess)
    {
        <div class="toast toast-success">Profile saved successfully!</div>
    }

    <div class="form-group avatar-group">
        <label>Avatar</label>
        <div class="avatar-preview">
            <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
        </div>
        <input type="text" value="@_avatarUrl" @onchange="e => _avatarUrl = e.Value?.ToString() ?? string.Empty" placeholder="Avatar URL" />
    </div>

    <div class="form-group">
        <label>Display Name</label>
        <input type="text" @bind="_displayName" />
    </div>

    <div class="form-group">
        <label>Email</label>
        <input type="email" @bind="_email" />
    </div>

    <div class="form-group">
        <label>Bio</label>
        <textarea rows="4" @bind="_bio"></textarea>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile Profile { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_saving)
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        _displayName = Profile.DisplayName;
        _email = Profile.Email;
        _avatarUrl = Profile.AvatarUrl;
        _bio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        StateHasChanged();
    }

    private void Discard()
    {
        LoadFromProfile();
    }
}

@namespace sv_de4e92b61854483da75d1cdae0b374ba.Components.Pages.Settings
@using sv_de4e92b61854483da75d1cdae0b374ba.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_showSuccess)
    {
        <div class="toast toast-success">Preferences saved!</div>
    }

    <div class="toggle-group">
        <label class="toggle-item">
            <span>Email Notifications</span>
            <input type="checkbox" @bind="_emailNotifications" />
        </label>

        <label class="toggle-item">
            <span>Push Notifications</span>
            <input type="checkbox" @bind="_pushNotifications" />
        </label>

        <label class="toggle-item">
            <span>Weekly Digest</span>
            <input type="checkbox" @bind="_weeklyDigest" />
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in _channels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@_mutedChannels.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Preferences")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    [Parameter]
    public List<string> AvailableChannels { get; set; } = ["general", "announcements", "random", "engineering", "design"];

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _channels = new();
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_saving)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            _channels = AvailableChannels;
        }
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        StateHasChanged();
    }
}

@namespace sv_de4e92b61854483da75d1cdae0b374ba.Components.Pages.Settings
@using sv_de4e92b61854483da75d1cdae0b374ba.Services

<div class="settings-section">
    <h2>Security</h2>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast @(_isError ? "toast-error" : "toast-success")">@_message</div>
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
        </button>

        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label>Current Password</label>
                    <input type="password" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label>New Password</label>
                    <input type="password" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label>Confirm New Password</label>
                    <input type="password" @bind="_confirmPassword" />
                </div>
                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-item">
        <div class="security-item-header">
            <h3>Two-Factor Authentication</h3>
            <span class="status-indicator @(Settings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="text-muted">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    @if (_confirmRevokeSessionId is not null)
    {
        <div class="confirmation-dialog">
            <p>Are you sure you want to revoke this session?</p>
            <div class="button-group">
                <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Yes, Revoke</button>
                <button class="btn btn-secondary" @onclick="() => _confirmRevokeSessionId = null">Cancel</button>
            </div>
        </div>
    }

    <div class="sessions-table-wrapper">
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="text-muted">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public SecuritySettings Settings { get; set; } = default!;

    [Parameter]
    public string CurrentSessionId { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _confirmRevokeSessionId;
    private string _message = "";
    private bool _isError;

    private async Task ChangePasswordAsync()
    {
        if (_newPassword != _confirmPassword)
        {
            ShowMessage("Passwords do not match.", isError: true);
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowMessage("New password cannot be empty.", isError: true);
            return;
        }

        _changingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            ShowMessage("Password updated successfully.", isError: false);
        }
        catch
        {
            ShowMessage("Failed to change password.", isError: true);
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void RequestRevoke(string sessionId)
    {
        _confirmRevokeSessionId = sessionId;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_confirmRevokeSessionId is not null)
        {
            await OnRevokeSession.InvokeAsync(_confirmRevokeSessionId);
            _confirmRevokeSessionId = null;
        }
    }

    private void ShowMessage(string text, bool isError)
    {
        _message = text;
        _isError = isError;
        _ = HideMessageAsync();
    }

    private async Task HideMessageAsync()
    {
        await Task.Delay(3000);
        _message = "";
        StateHasChanged();
    }
