<div class="settings-section">
    <h2>Security</h2>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast @(_isError ? "toast-error" : "toast-success")">@_message</div>
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
        </button>

        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label>Current Password</label>
                    <input type="password" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label>New Password</label>
                    <input type="password" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label>Confirm New Password</label>
                    <input type="password" @bind="_confirmPassword" />
                </div>
                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-item">
        <div class="security-item-header">
            <h3>Two-Factor Authentication</h3>
            <span class="status-indicator @(Settings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="text-muted">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    @if (_confirmRevokeSessionId is not null)
    {
        <div class="confirmation-dialog">
            <p>Are you sure you want to revoke this session?</p>
            <div class="button-group">
                <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Yes, Revoke</button>
                <button class="btn btn-secondary" @onclick="() => _confirmRevokeSessionId = null">Cancel</button>
            </div>
        </div>
    }

    <div class="sessions-table-wrapper">
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="text-muted">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public SecuritySettings Settings { get; set; } = default!;

    [Parameter]
    public string CurrentSessionId { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _confirmRevokeSessionId;
    private string _message = "";
    private bool _isError;

    private async Task ChangePasswordAsync()
    {
        if (_newPassword != _confirmPassword)
        {
            ShowMessage("Passwords do not match.", isError: true);
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowMessage("New password cannot be empty.", isError: true);
            return;
        }

        _changingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            ShowMessage("Password updated successfully.", isError: false);
        }
        catch
        {
            ShowMessage("Failed to change password.", isError: true);
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void RequestRevoke(string sessionId)
    {
        _confirmRevokeSessionId = sessionId;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_confirmRevokeSessionId is not null)
        {
            await OnRevokeSession.InvokeAsync(_confirmRevokeSessionId);
            _confirmRevokeSessionId = null;
        }
    }

    private void ShowMessage(string text, bool isError)
    {
        _message = text;
        _isError = isError;
        _ = HideMessageAsync();
    }

    private async Task HideMessageAsync()
    {
        await Task.Delay(3000);
        _message = "";
        StateHasChanged();
    }
}

