@namespace sv_de4e92b61854483da75d1cdae0b374ba.Components.Pages.Settings
@using sv_de4e92b61854483da75d1cdae0b374ba.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_showSuccess)
    {
        <div class="toast toast-success">Preferences saved!</div>
    }

    <div class="toggle-group">
        <label class="toggle-item">
            <span>Email Notifications</span>
            <input type="checkbox" @bind="_emailNotifications" />
        </label>

        <label class="toggle-item">
            <span>Push Notifications</span>
            <input type="checkbox" @bind="_pushNotifications" />
        </label>

        <label class="toggle-item">
            <span>Weekly Digest</span>
            <input type="checkbox" @bind="_weeklyDigest" />
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in _channels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@_mutedChannels.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Preferences")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    [Parameter]
    public List<string> AvailableChannels { get; set; } = ["general", "announcements", "random", "engineering", "design"];

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _channels = new();
    private bool _saving;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_saving)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            _channels = AvailableChannels;
        }
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        StateHasChanged();
    }
}

