.sidebar-item:hover {
    background: #e9ecef;
    color: #333;
}

.sidebar-item.active {
    background: #e3f2fd;
    color: #1976d2;
    font-weight: 600;
    border-left: 3px solid #1976d2;
}

.sidebar-icon {
    font-size: 1.2rem;
}

