.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    margin-bottom: 1.5rem;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    border: none;
    background: #f8f9fa;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-body {
    padding: 1rem;
