    border: 1px solid #a5d6a7;
}

.toast-error {
    background: #fbe9e7;
    color: #d32f2f;
    border: 1px solid #ef9a9a;
}

/* Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    padding: 1.5rem;
    margin-top: 1.5rem;
