}

.preview-theme-dark {
    background: #333;
    color: #eee;
    border-color: #555;
}

.preview-theme-dark .preview-card {
    border-color: #555;
    background: #444;
}

.preview-theme-light {
    background: #fff;
    color: #333;
}

.preview-theme-system {
    background: #fafafa;
    color: #333;
}

.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

/* Utility */
.text-muted {
    color: #888;
    font-size: 0.85rem;
}

.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    color: #888;
